CREATE TABLE IF NOT EXISTS "vouchers" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(100) UNIQUE NOT NULL,
  "title" varchar(255) NOT NULL,
  "description" text,
  "discount_type" varchar(30) NOT NULL,
  "discount_value" decimal(12,2) NOT NULL,
  "max_discount_amount" decimal(12,2),
  "min_order_value" decimal(12,2) NOT NULL DEFAULT 0.00,
  "total_usage_limit" int,
  "used_count" int NOT NULL DEFAULT 0,
  "usage_per_user_limit" int,
  "start_date" timestamp NOT NULL,
  "end_date" timestamp NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_vouchers_discount_type CHECK (discount_type IN ('PERCENTAGE', 'FIXED_AMOUNT', 'PERCENT', 'FIXED')),
  CONSTRAINT chk_vouchers_discount_value CHECK (discount_value > 0),
  CONSTRAINT chk_vouchers_dates CHECK (end_date >= start_date)
);

CREATE INDEX IF NOT EXISTS idx_vouchers_code_active ON "vouchers" ("code", "is_active");
CREATE INDEX IF NOT EXISTS idx_vouchers_dates ON "vouchers" ("start_date", "end_date");

